import re
import sys

LINE_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                time, module, message = m.groups()
                rows.append({"time": time, "module": module, "message": message})
    return rows


def to_markdown(rows):
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        msg = r["message"].replace("|", "\\|")
        lines.append(f"| {r['time']} | {r['module']} | {msg} |")
    return "\n".join(lines)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"usage: {sys.argv[0]} LOGFILE")
    sys.stdout.reconfigure(encoding="utf-8")
    print(to_markdown(parse_errors(sys.argv[1])))
EOF
